import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ __launch_bounds__(256) void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int CinPerGroup, int K,
    int stride, int padding, int dilation,
    int groups, int CoutPerGroup,
    int Hout, int Wout,
    int TileIH, int TileIW)
{
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 32;
  constexpr int Threads    = TILE_OH * TILE_OW;
  constexpr int CcPerBlock = 8;
  const int tid = threadIdx.x;
  const int ty  = tid / TILE_OW;
  const int tx  = tid % TILE_OW;
  const int CoTiles = (Cout + CcPerBlock - 1) / CcPerBlock;
  const int co_tile = blockIdx.z % CoTiles;
  const int n       = blockIdx.z / CoTiles;
  const int co_base = co_tile * CcPerBlock;
  const int oh_tile0 = blockIdx.y * TILE_OH;
  const int ow_tile0 = blockIdx.x * TILE_OW;
  const int oh = oh_tile0 + ty;
  const int ow = ow_tile0 + tx;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int KK = K * K;
  const int R  = CinPerGroup * KK;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXn = (int64_t)Cin * sXc;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYn = (int64_t)Cout * sYc;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn = Y + (int64_t)n * sYn;
  extern __shared__ unsigned char smem_raw[];
  T* sW = reinterpret_cast<T*>(smem_raw);
  T* sX = sW + CcPerBlock * KK;
  int cin_start_arr[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int co = co_base + cc;
    int group = (co < Cout) ? (co / CoutPerGroup) : 0;
    cin_start_arr[cc] = group * CinPerGroup;
  }
  bool same_group = true;
  #pragma unroll
  for (int cc = 1; cc < CcPerBlock; ++cc) {
    if (cin_start_arr[cc] != cin_start_arr[0]) same_group = false;
  }
  float acc[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int co = co_base + cc;
    acc[cc] = (B != nullptr && co < Cout) ? (float)B[co] : 0.0f;
  }
  const int ih0 = oh_tile0 * stride - padding;
  const int iw0 = ow_tile0 * stride - padding;
  if (same_group) {
    const int cin_start = cin_start_arr[0];
    const int tile_elems = TileIH * TileIW;
    for (int cin_local = 0; cin_local < CinPerGroup; ++cin_local) {
      const int cin = cin_start + cin_local;
      const T* Xc = Xn + (int64_t)cin * sXc;
      for (int idx = tid; idx < tile_elems; idx += Threads) {
        int r = idx / TileIW;
        int c = idx - r * TileIW;
        int ih = ih0 + r;
        int iw = iw0 + c;
        T val = T(0);
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          val = Xc[(int64_t)ih * Win + iw];
        }
        sX[idx] = val;
      }
      for (int kk = tid; kk < KK; kk += Threads) {
        int r_global = cin_local * KK + kk;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int co = co_base + cc;
          T wval = T(0);
          if (co < Cout) {
            wval = W[(int64_t)co * R + r_global];
          }
          sW[cc * KK + kk] = wval;
        }
      }
      __syncthreads();
      if (valid_out) {
        for (int kh = 0; kh < K; ++kh) {
          int r = ty * stride + kh * dilation;
          const T* sX_row = sX + r * TileIW;
          for (int kw = 0; kw < K; ++kw) {
            int c = tx * stride + kw * dilation;
            float xval = (float)sX_row[c];
            int kk = kh * K + kw;
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              acc[cc] += xval * (float)sW[cc * KK + kk];
            }
          }
        }
      }
      __syncthreads();
    }
  } else {
    if (valid_out) {
      #pragma unroll
      for (int cc = 0; cc < CcPerBlock; ++cc) {
        int co = co_base + cc;
        if (co >= Cout) continue;
        int cin_start = cin_start_arr[cc];
        float a = acc[cc];
        for (int cin_local = 0; cin_local < CinPerGroup; ++cin_local) {
          int cin = cin_start + cin_local;
          const T* Xc = Xn + (int64_t)cin * sXc;
          for (int kh = 0; kh < K; ++kh) {
            int ih = oh * stride - padding + kh * dilation;
            if ((unsigned)ih >= (unsigned)H) continue;
            for (int kw = 0; kw < K; ++kw) {
              int iw = ow * stride - padding + kw * dilation;
              if ((unsigned)iw >= (unsigned)Win) continue;
              float xval = (float)Xc[(int64_t)ih * Win + iw];
              float wval = (float)W[(int64_t)co * R + cin_local * KK + kh * K + kw];
              a += xval * wval;
            }
          }
        }
        acc[cc] = a;
      }
    }
  }
  if (valid_out) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int co = co_base + cc;
      if (co >= Cout) continue;
      Yn[(int64_t)co * sYc + (int64_t)oh * Wout + ow] = static_cast<T>(acc[cc]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin/groups, K, K]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout        = w.size(0);
  int64_t CinPerGroup = w.size(1);
  int64_t K           = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square");
  TORCH_CHECK(CinPerGroup * groups == Cin, "Cin/groups mismatch");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  int64_t CoutPerGroup = Cout / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 32;
  constexpr int CcPerBlock = 8;
  constexpr int Threads    = TILE_OH * TILE_OW;
  const int64_t CoTiles = (Cout + CcPerBlock - 1) / CcPerBlock;
  int TileIH = (int)((int64_t)(TILE_OH - 1) * stride + (int64_t)(K - 1) * dilation + 1);
  int TileIW = (int)((int64_t)(TILE_OW - 1) * stride + (int64_t)(K - 1) * dilation + 1);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + TILE_OW - 1) / TILE_OW),
      (unsigned)((Hout + TILE_OH - 1) / TILE_OH),
      (unsigned)(N * CoTiles)
  );
  size_t smem_bytes = (size_t)(CcPerBlock * K * K + TileIH * TileIW) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  }
  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)CinPerGroup, (int)K,
      (int)stride, (int)padding, (int)dilation,
      (int)groups, (int)CoutPerGroup,
      (int)Hout, (int)Wout,
      TileIH, TileIW
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a custom cooperative-tiled CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        Cout = self.out_channels
        Cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(Cout, Cin_per_group, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

